INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69442, 'spa', 'Jesucristo', 'El nombre personal del Mesías, el Hijo de Dios encarnado, Salvador y Señor — la figura central del Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69443, 'spa', 'muchos, numerosos — Sentido cuantitativo que indica un gran número de personas o', 'muchos, numerosos — Sentido cuantitativo que indica un gran número de personas o cosas. En Hechos 9:23 «habían pasado muchos días», en Hechos 12:12 «muchos» se habían reunido a orar, y en Lucas 23:9 Herodes interrogó a Jesús «extensamente» (literalmente «con muchas palabras»). Mientras el sentido 1 enfatiza grado o magnitud, este sentido destaca el conteo o la pluralidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69444, 'spa', 'digno, competente — De personas', 'digno, competente — De personas: digno, apto, competente o cualificado para un papel o tarea. La confesión del Bautista «no soy digno de llevar sus sandalias» (Mt 3:11) y la del centurión «no soy digno de que entres bajo mi techo» (Mt 8:8; Lc 7:6) están entre las expresiones de humildad más conmovedoras del Nuevo Testamento. El uso paulino en 2 Corintios 2:16 («¿quién es competente para estas cosas?») amplía el alcance.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69445, 'spa', 'considerable, de gran grado — Indica grado, extensión o duración considerable', 'considerable, de gran grado — Indica grado, extensión o duración considerable: grande en tamaño, intensidad o lapso de tiempo. En Mateo 28:12 los principales sacerdotes dan a los soldados «una suma considerable de dinero», y en Lucas 8:27 un hombre había estado endemoniado «por mucho tiempo». Marcos 10:46 describe «una multitud considerable» saliendo de Jericó con Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69450, 'spa', 'suficiente, bastante — Suficiente o bastante en cantidad o grado para satisfacer', 'suficiente, bastante — Suficiente o bastante en cantidad o grado para satisfacer una necesidad particular. En Lucas 22:38 los discípulos dicen «aquí hay dos espadas» y Jesús responde «basta». En 2 Corintios 2:6 el castigo impuesto por la mayoría «es suficiente». Transmite la idea de adecuación justa para el propósito requerido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69456, 'spa', 'fianza, garantía — Término jurídico-comercial sustantivado (τὸ ἱκανόν) que signi', 'fianza, garantía — Término jurídico-comercial sustantivado (τὸ ἱκανόν) que significa fianza, depósito de garantía o caución. En Hechos 17:9 las autoridades de Tesalónica liberan a Jasón y los demás solo después de «recibir fianza» (λαβόντες τὸ ἱκανόν) de ellos. Es una especialización del significado nuclear: lo que es «suficiente» para garantizar una obligación se cristaliza en un instrumento financiero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69460, 'spa', 'Suficiencia divina', 'Pablo declara que la ἱκανότης apostólica —competencia o suficiencia— proviene de Dios, no de uno mismo (2 Corintios 3:5). El sustantivo denota aptitud o cualificación para una tarea. En contexto, se refiere a la competencia para el ministerio del nuevo pacto: los apóstoles no son autosuficientes, sino capacitados por Dios. El uso clásico abarca suficiencia cuantitativa y competencia cualitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69462, 'spa', 'Súplica ferviente', 'Hebreos describe a Jesús ofreciendo δεήσεις τε καὶ ἱκετηρίας —oraciones y súplicas (5:7)— durante su vida encarnada, con gran clamor y lágrimas. El sustantivo ἱκετηρία significaba literalmente la rama de olivo portada por los suplicantes, extendiéndose luego a la súplica misma: ruego ardiente y petición ferviente. El contexto evoca las oraciones agónicas de Getsemaní.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69463, 'spa', 'Humedad del suelo', 'En la parábola, la semilla sobre terreno rocoso se seca διὰ τὸ μὴ ἔχειν ἰκμάδα —por falta de humedad (Lucas 8:6). El sustantivo denota contenido líquido, aquí la humedad del suelo esencial para el crecimiento vegetal. El uso clásico aplica ἰκμάς a humores corporales, savia vegetal y humedad terrestre. El contexto agrícola subraya la necesidad de hidratación sostenida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69464, 'spa', 'Iconio', 'Iconio (Ἰκόνιον), antigua ciudad del centro-sur de Asia Menor en la provincia romana de Galacia, correspondiente a la actual Konya en Turquía. Fue un importante centro urbano en la ruta comercial Via Sebaste y parada significativa en el primer viaje misionero de Pablo. Pablo y Bernabé predicaron con valentía en su sinagoga (Hch 14:1) y enfrentaron oposición tanto judía como gentil (Hch 14:2-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69466, 'spa', 'Dador alegre', 'Pablo declara que θεὸς ἱλαρὸν δότην ἀγαπᾷ —Dios ama al dador alegre (2 Corintios 9:7). El adjetivo ἱλαρός describe a alguien gozoso, animado, dispuesto: lo opuesto a reticente u obligado. El dicho subraya que importa el espíritu de la generosidad: dar con gozo, no por coacción. El uso clásico aplica ἱλαρός a la luz alegre y la disposición amable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69467, 'spa', 'Alegría en servir', 'Pablo instruye que quien muestra misericordia lo haga ἐν ἱλαρότητι —con alegría (Romanos 12:8). El sustantivo denota gozo o disposición alegre: la cualidad de actuar con ánimo luminoso y no de mala gana. El ministerio de misericordia requiere no solo acción sino espíritu gozoso: compasión ejercida con alegría. Las fuentes clásicas emplean ἱλαρότης para regocijo y buen ánimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69472, 'spa', 'Provincia romana adriática', 'Pablo describe el alcance de su ministerio desde Jerusalén ἄχρι τοῦ Ἰλλυρικοῦ — hasta el Ilírico (Rom 15:19). La región designa la provincia romana en la costa oriental del Adriático, al noroeste de Macedonia, la frontera occidental de los viajes documentados de Pablo. Si predicó allí o solo alcanzó sus límites no queda claro en el texto, pero define el arco de su misión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69473, 'spa', 'Correa de cuero', 'Tira o correa de cuero empleada en el Nuevo Testamento para dos objetos distintos: la cinta o atadura de una sandalia y las correas de sujeción usadas en el castigo romano. Los evangelios sinópticos y Juan registran la confesión del Bautista de no ser digno de desatar el ἱμάς de la sandalia del Mesías (Mr 1:7; Lc 3:16; Jn 1:27), convirtiendo la humilde correa en icono de suprema humildad. En Hch 22:25 Pablo invoca su ciudadanía romana al ser atado con estas correas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69475, 'spa', 'Vestidura, ropa en general', 'Ropa o vestiduras en sentido general e inespecífico, apareciendo frecuentemente en plural con el significado de ''ropas'' o ''lo que uno viste''. Este es el uso dominante en 54 ocurrencias. Pasajes clave incluyen la mujer que toca las vestiduras de Jesús (Mt 9:20), los vestidos viejos que reciben remiendo nuevo (Mt 9:16) y las multitudes que tienden sus mantos (Mt 21:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69479, 'spa', 'Manto exterior, capa', 'El manto o capa exterior específico que se llevaba sobre la túnica (χιτών), prenda que podía quitarse, asirse o tenderse. En Mt 5:40 Jesús contrasta el χιτών (túnica interior) con el ἱμάτιον (manto exterior), haciendo explícita la distinción. Bartimeo arrojando su manto (Mc 10:50) y la instrucción de no volver por el ἱμάτιον (Mt 24:18) ilustran este sentido específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69485, 'spa', 'Ropa, vestimenta', 'Vestimenta o ropa considerada en su conjunto: las prendas que una persona lleva, vistas colectivamente. Se emplea en contextos variados del NT: el lujoso atuendo de los cortesanos (Lc 7:25), la transformación radiante de la apariencia de Jesús (Lc 9:29), el reparto de los vestidos de Jesús cumpliendo el Salmo 22:18 (Mt 27:35; Jn 19:24) y la declaración de independencia material de Pablo (Hch 20:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69487, 'spa', 'Anhelo afectuoso', 'Pablo describe su ministerio apostólico con el participio ὁμειρόμενοι — anhelándoos (1 Tes 2:8). El verbo (variante de ἱμείρω) denota un anhelo afectuoso, un deseo ardiente y cálido. La poesía clásica lo emplea para el deseo apasionado o el amor. El uso paulino subraya la dimensión personal y entrañable del ministerio: no un deber profesional, sino un anhelo del corazón por el bienestar de los tesalonicenses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69488, 'spa', 'propósito/final', 'Introduce cláusulas de propósito o finalidad, expresando la intención o el objetivo de una acción — ''para que'', ''a fin de que''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69489, 'spa', 'contenido/epexegético', 'Introduce cláusulas de contenido o epexegéticas que explican o completan el significado de un verbo, sustantivo o adjetivo — ''que''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69494, 'spa', 'Jope — la ciudad portuaria mediterránea (actual Jaffa/Yafo), ubicada en la costa', 'Jope — la ciudad portuaria mediterránea (actual Jaffa/Yafo), ubicada en la costa palestina. En Hechos sirve como escenario del milagro de Pedro al resucitar a Tabita de entre los muertos (Hch 9:36-43), su estancia en casa de Simón el curtidor (Hch 9:43; 10:6, 32), y su visión en la azotea que declaró limpios todos los alimentos (Hch 10:5-8; 11:5, 13). Jope funciona como puente geográfico y narrativo entre la misión judía y la apertura del evangelio a los gentiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69495, 'spa', 'El río Jordán, el curso de agua principal de Palestina que fluye desde el Mar de', 'El río Jordán, el curso de agua principal de Palestina que fluye desde el Mar de Galilea hasta el Mar Muerto. En el NT aparece principalmente como el lugar del ministerio bautismal de Juan el Bautista (Mt 3:5-6; Mr 1:5) y del propio bautismo de Jesús (Mt 3:13; Mr 1:9). También funciona como marcador de frontera geográfica, con «al otro lado del Jordán» designando la región de Transjordania (Mt 4:15, 25; 19:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69496, 'spa', 'Corrosión y veneno', 'El sentido único abarca sustancias corrosivas o venenosas, ya sea en sentido literal (herrumbre sobre el metal) o metafórico (habla ponzoñosa). Santiago emplea ambos usos: el óxido literal como testimonio contra la riqueza acumulada (5:3) y el veneno metafórico describiendo el potencial letal de la lengua (3:8). Romanos cita el salmo sobre el veneno de serpiente bajo los labios de los impíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69497, 'spa', 'De Judá, tribu/territorio', 'El patriarca Judá, su tribu o su territorio, empleado en genitivo para denotar origen, pertenencia o referencia geográfica. Mateo 2:6 nombra ''la tierra de Judá'' (γῆ Ἰούδα) en el oráculo sobre Belén; Lucas 1:39 sitúa la visitación de María ''en la región montañosa de Judá''; y Hebreos 7:14 declara que ''nuestro Señor procedió de Judá''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69500, 'spa', 'Ἰωδά, nombre personal', 'Nombre personal Ἰωδά (variante: Joda) en Lucas 3:26, un antepasado en la genealogía de Jesús por la línea de María. Esta figura aparece únicamente aquí y es distinta del patriarca Judá, aunque la forma genitiva es morfológicamente idéntica. Pertenece a generaciones no atestiguadas entre David y el período postexílico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69501, 'spa', 'Judea (region geografica)', 'La region geografico-politica de Judea (Ἰουδαία, literalmente ''la [tierra] judia''), la provincia meridional de la Palestina romana centrada en Jerusalen y que se extiende desde las colinas de Judea hasta el Mar Muerto y el Neguev. Funciona como escenario narrativo del nacimiento de Jesus (Mt 2:1, 5-6), del ministerio bautismal de Juan (Mt 3:1; Mc 1:5) y de la base misionera de la iglesia primitiva (Hch 1:8; 8:1; 9:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69504, 'spa', 'Adoptar prácticas judías', 'Pablo desafía a Pedro: πῶς τὰ ἔθνη ἀναγκάζεις Ἰουδαΐζειν; (Gál 2:14) — ¿cómo obligas a los gentiles a judaizar? El verbo significa adoptar prácticas judías, vivir según costumbres judías o exigir marcas identitarias judías como la circuncisión, las leyes dietéticas y la observancia de festividades. La cuestión central es si los creyentes gentiles deben hacerse culturalmente judíos para ser plenamente cristianos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69505, 'spa', 'Relativo a lo judío', 'Pablo advierte a Tito contra Ἰουδαϊκοῖς μύθοις — mitos judíos (Tito 1:14) — y mandamientos de quienes rechazan la verdad. El adjetivo describe enseñanzas arraigadas en la tradición judía: posiblemente genealogías especulativas, disputas haláquicas o leyendas apócrifas promovidas en Creta. La advertencia no apunta al judaísmo en sí, sino a falsos maestros que usan la tradición judía para promover el error.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69506, 'spa', 'A la manera judía', 'La confrontación de Pablo pregunta: εἰ σὺ Ἰουδαῖος ὑπάρχων ἐθνικῶς καὶ οὐχὶ Ἰουδαϊκῶς ζῇς (Gál 2:14) — si tú, siendo judío, vives como gentil y no judaicamente. El adverbio Ἰουδαϊκῶς describe vivir según las costumbres judías: guardar las leyes dietéticas, observar las festividades, mantener los códigos de pureza. Pedro había comido con gentiles hasta que llegó el grupo de la circuncisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69507, 'spa', 'judío, persona judía', 'Una persona identificada como judía por etnia, religión o pertenencia a la alianza. Se emplea sustantivado en todos los casos, números y géneros. La traducción interlingüística es prácticamente unánime: «judíos» (esp.), Juifs (fr.), Juden (al.). En el Evangelio de Juan especialmente, el término se estrecha con frecuencia para referirse a las autoridades religiosas que se oponen a Jesús (Jn 5:16; 7:1), aunque también conserva su sentido étnico amplio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69517, 'spa', 'Judea, región judía', 'Referencia geográfica a Judea (ἡ Ἰουδαία, sc. γῆ), la región meridional de Palestina asociada con la tribu de Judá. En Jn 3:22, Jesús va «a la tierra de Judea» (εἰς τὴν Ἰουδαίαν γῆν), y las traducciones al español («Judea») y al alemán (Judäa) distinguen este sentido territorial del étnico. Se preserva el patrón del griego clásico donde el adjetivo femenino con un sustantivo sobreentendido (γῆ) funciona como topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69520, 'spa', 'Judas / Juda (nombre propio)', 'El nombre propio Ἰούδας (del hebreo יְהוּדָה), aplicado a multiples individuos en el NT: el patriarca Juda hijo de Jacob (Mt 1:2-3; Ap 5:5; 7:5), Judas Iscariote el traidor (Mt 10:4; 26:14-47; Jn 13:2, 26-30), Judas hijo de Jacobo el apostol (Lc 6:16; Jn 14:22; Hch 1:13), Judas hermano del Senor (Mt 13:55; Jud 1), Judas de Galilea (Hch 5:37) y Judas Barsabas (Hch 15:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69524, 'spa', 'Cristiana en Roma', 'Los saludos finales de Pablo incluyen a Ἰουλίαν (Rom 16:15), una mujer de la comunidad cristiana romana. Aparece junto a Filólogo, Nereo y su hermana, y Olimpas, posiblemente un grupo doméstico. El nombre Julia era común en Roma, especialmente entre personas vinculadas a la gens Julia imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69526, 'spa', 'Apóstol notable', 'Pablo saluda a Ἰουνιᾶν (Rom 16:7) junto con Andrónico: parientes, compañeros de prisión, «destacados entre los apóstoles», creyentes antes que Pablo. El acusativo puede ser masculino (Junias) o femenino (Junia). Los padres de la iglesia lo leyeron como femenino; Junia era nombre romano común, Junias extremadamente raro. Si es Junia, sería apóstol femenina encarcelada por Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69527, 'spa', 'Sobrenombre compartido', 'Este sentido identifica el cognomen o sobrenombre compartido por tres individuos distintos. El José Justo de Hechos 1:23 representa la gobernanza eclesial primitiva, escogiendo liderazgo apostólico mediante oración y sorteo. El Ticio Justo de Hechos 18:7 representa la comunidad de temerosos de Dios y el movimiento de iglesias en casas. El Jesús Justo de Colosenses encarna la colaboración paulina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69529, 'spa', 'Caballería apocalíptica', 'La visión de la sexta trompeta incluye τὸ ἀρίθμημα τοῦ στρατεύματος τοῦ ἱππικοῦ, el número de la caballería (Apocalipsis 9:16): doscientos millones. El adjetivo ἱππικός designa lo relativo a caballos o jinetes, aquí un vasto ejército montado. El uso clásico distingue ἱππικός (caballería) de πεζός (infantería).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69530, 'spa', 'Caballo', 'Caballo: Un caballo, el animal equino domesticado, usado predominantemente en contextos apocalípticos e ilustrativos. En Apocalipsis aparece en las visiones de los cuatro jinetes (Ap 6:2, 4, 5, 8), la caballería demoníaca (Ap 9:7, 9, 17, 19) y los ejércitos del cielo montados en caballos blancos (Ap 19:11, 14, 18, 19, 21). Santiago 3:3 usa el caballo y su freno como analogía para controlar la lengua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69533, 'spa', 'Isaac', 'Isaac: El patriarca Isaac, hijo de Abraham y Sara, nacido según la promesa divina. Las 20 apariciones se refieren a esta única figura histórica y teológica, ya sea en listas genealógicas (Mt 1:2), en la referencia de Jesús al Dios ''de Abraham, Isaac y Jacob'' (Mt 22:32; Mc 12:26), o en el argumento de Pablo sobre los hijos de la promesa (Ro 9:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69535, 'spa', 'Semejantes a ángeles', 'Jesús enseña que los creyentes resucitados serán ἰσάγγελοι, iguales a los ángeles (Lucas 20:36). El adjetivo compuesto (ἴσος + ἄγγελος) indica compartir características angélicas, específicamente la inmortalidad: «ya no pueden morir». El contexto responde a los saduceos sobre el matrimonio en la resurrección; la vida resucitada trasciende el matrimonio porque son inmortales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69536, 'spa', 'Tribu de Isacar', 'Este nombre propio aparece en la visión de Juan sobre los siervos sellados de las tribus de Israel. Las glosas multilingües preservan la forma fonética hebrea, manteniendo la identidad tribal en la traducción. Apocalipsis 7:7 enumera a Isacar en quinto lugar en el censo apocalíptico, entre Gad y Zabulón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69537, 'spa', 'Iscariote (epíteto de Judas) — sobrenombre distintivo de Judas el traidor, y en ', 'Iscariote (epíteto de Judas) — sobrenombre distintivo de Judas el traidor, y en una ocasión de su padre Simón (Jn 6:71). Probablemente derivado del hebreo ''hombre de Queriot'' (אִישׁ קְרִיּוֹת), una localidad del sur de Judá (Jos 15:25), lo que señalaría a Judas como quizás el único apóstol no galileo. El epíteto aparece en cada lista apostólica (Mt 10:4; Mc 3:19; Lc 6:16; Hch 1:25 implícito) y a lo largo de los relatos de la traición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69541, 'spa', 'Igual, mismo, concordante', 'Igual, equivalente o concordante en cantidad, cualidad o estatus, implicando una correspondencia medida entre dos cosas. Los trabajadores de la viña protestan porque el amo ha hecho a los últimos ἴσους —iguales— a ellos (Mt 20:12), exponiendo el escándalo de la gracia. En el juicio de Jesús, los falsos testigos no logran dar testimonios ἴσαι (concordantes, coincidentes) (Mr 14:56, 59), donde el sentido se acerca a ''coincidente''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69544, 'spa', 'Equidad distributiva', 'El sentido enfatiza la distribución y el trato equitativos. El argumento de Pablo en 2 Corintios sobre la colecta para Jerusalén apela a la igualdad como principio: la abundancia presente de los corintios debe suplir la necesidad ajena, anticipando reciprocidad futura. No se trata de uniformidad absoluta, sino de equilibrar abundancia y carencia en el cuerpo. En Colosenses, la igualdad se extiende a las relaciones sociales entre amos y siervos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69545, 'spa', 'De igual valor', 'Pedro emplea este término para describir la naturaleza democrática de la fe salvífica. El español ''de igual valor'' y el alemán ''gleichwertig'' capturan el núcleo semántico de equivalencia en valor. Lo que los apóstoles poseían por haber caminado con Jesús, los creyentes posteriores lo poseen por medio del Espíritu: una fe de idéntica calidad y honor, eliminando toda distinción jerárquica en el acceso a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69546, 'spa', 'De igual alma', 'La aplicación exclusiva que hace Pablo de ἰσόψυχος a Timoteo revela su intensidad: describe a alguien cuya alma misma resuena con la preocupación pastoral de Pablo. El español ''de igual alma'' y el alemán ''gleichgesinnt'' preservan la intimidad relacional. No se trata de alineamiento organizacional, sino de parentesco espiritual, donde dos personas se preocupan por las mismas cosas y por las mismas razones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69547, 'spa', 'Israel (nación/pueblo/patriarca)', 'Nombre propio semítico que designa al pueblo del pacto de Dios en el Nuevo Testamento, abarcando la nación (Mt 2:6; Lc 1:54), la tierra (Mt 2:20-21), las doce tribus (Mt 19:28) y, por extensión teológica, la comunidad escatológica (''el Israel de Dios'', Gá 6:16). La distinción paulina entre Israel ''según la carne'' (1 Co 10:18) e Israel espiritual no crea una entidad separada, sino que profundiza la identidad pactual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69550, 'spa', 'Israelita', 'Miembro de la nación de Israel, usado como designación de privilegio teocrático e identidad pactual más que de mera etnicidad. En el NT aparece en dos patrones principales: como vocativo en discursos públicos (''¡Varones israelitas!'' en Hch 2:22, 3:12, 5:35, 13:16, 21:28) y como predicado de pertenencia al pacto (Ro 9:4, 11:1; 2 Co 11:22). La declaración de Jesús sobre Natanael como ''verdaderamente un israelita'' refuerza la dimensión teológica del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69554, 'spa', 'estar de pie', 'Intransitivo: estar de pie, hallarse en posición erguida — el sentido físico-posicional central. Es el sentido dominante (107 veces), abarcando multitudes junto al mar (Mt 13:2), obreros de pie ociosos en la plaza (Mt 20:3, 6) y la apocalíptica «abominación desoladora de pie donde no debe» (Mr 13:14). El árabe waqafa y el coreano seo-itda marcan consistentemente la posición corporal estática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69558, 'spa', 'poner, colocar', 'Transitivo causativo: poner, colocar o hacer que alguien o algo esté en una posición determinada. Aparece 17 veces con objeto directo: el diablo poniendo a Jesús en el pináculo (Mt 4:5), Jesús colocando a un niño en medio (Mt 18:2; Mr 9:36) y el Hijo del Hombre separando ovejas de cabritos poniéndolas a su derecha (Mt 25:33). El árabe aqāma (erigir, establecer) marca la acción agentiva de colocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69569, 'spa', 'mantenerse firme, perseverar', 'Intransitivo figurado: mantenerse firme, permanecer constante o resistir bajo presión — perseverancia moral y espiritual. Aparece 15 veces, de modo memorable en el axioma de Jesús «un reino dividido contra sí mismo no puede mantenerse en pie» (Mt 12:25; Mr 3:24-26) y en las exhortaciones de Pablo a «estar firmes» (Ef 6:11, 13-14). El español «mantenerse firme» y «permanecer» captan este sentido de estabilidad interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69574, 'spa', 'detenerse, pararse', 'Intransitivo cesativo: detenerse, pararse o quedarse quieto tras un movimiento. Aparece 7 veces: la estrella deteniéndose sobre Belén (Mt 2:9), Jesús deteniéndose en el camino (Mt 20:32; Mr 10:49), la camilla funeraria quedándose quieta al toque de Jesús (Lc 7:14) y el flujo de sangre de la mujer que cesó (Lc 8:44). El español «detenerse» distingue claramente la cesación de la posición estática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69586, 'spa', 'establecer, confirmar', 'Transitivo abstracto: establecer, confirmar, sostener o ratificar — usado con leyes, pactos y propósitos divinos. Aparece 6 veces: establecer testimonio por dos o tres testigos (Mt 18:16), Dios señalando un día de juicio (Hch 17:31), Pablo insistiendo «confirmamos la ley» (Ro 3:31), e Israel procurando establecer su propia justicia (Ro 10:3). El español «establecer» marca el registro institucional y jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69607, 'spa', 'pesar, fijar precio', 'Un sentido comercial transitivo en Mt 26:15, donde los principales sacerdotes «pesaron» treinta piezas de plata para Judas. El español «pesaron» preserva la conexión antigua entre establecer un peso y fijar un precio. Este uso infrecuente hace eco de la traducción de la LXX de modismos hebreos basados en šeqal y se conecta con la práctica arcaica de colocar balanzas para pesar el pago.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69610, 'spa', 'Visitar para conocer', 'La cuidadosa elección de palabras de Pablo refuerza su argumento de que su evangelio vino por revelación, no por instrucción humana. El español ''para conocer'' y el alemán ''besuchen'' reflejan la naturaleza intencional del viaje. Pablo visitó a Pedro no como alumno ante un maestro, sino como un apóstol conociendo a otro, en una misión de quince días que no comprometió su llamado divino ni subordinó su autoridad apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69611, 'spa', 'Que posee gran fuerza, poder o robustez en grado positivo, usado de personas o f', 'Que posee gran fuerza, poder o robustez en grado positivo, usado de personas o fuerzas abstractas. Jesús habla del ''hombre fuerte'' que guarda su casa (Mt 12:29; Mc 3:27) y el viento se describe como ''fuerte'' en Mt 14:30. Apocalipsis lo usa para un ''ángel poderoso'' (Ap 5:2; 10:1; 18:21). Cubre tanto el vigor físico como la potencia espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69614, 'spa', 'El grado comparativo — más fuerte o más poderoso que otro — frecuentemente susta', 'El grado comparativo — más fuerte o más poderoso que otro — frecuentemente sustantivado como ''el más fuerte.'' La confesión de Juan el Bautista ''viene uno más poderoso que yo'' (Mt 3:11; Mc 1:7; Lc 3:16) es la instancia paradigmática. En la parábola, ''cuando viene uno más fuerte que él lo vence'' (Lc 11:22). La paradoja paulina de que la insensatez de Dios es ''más fuerte que los hombres'' (1 Co 1:25) invierte las expectativas humanas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69621, 'spa', 'Extensión metafórica a fuerzas o condiciones impersonales, con el significado de', 'Extensión metafórica a fuerzas o condiciones impersonales, con el significado de severo, violento o intenso. Lucas 15:14 describe un ''hambre severa'' que sobrevino en la tierra donde el hijo pródigo había malgastado su herencia. Este uso, aunque raro en el NT, está bien atestiguado en el griego clásico para sabores fuertes, suelo duro y condiciones intensas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69623, 'spa', 'Fuerza, poder, potencia — capacidad inherente, física o espiritual, para actuar ', 'Fuerza, poder, potencia — capacidad inherente, física o espiritual, para actuar con vigor. Se usa en la obligación humana de amar a Dios con todas las fuerzas según la cita del Shemá (Mc 12:30, 33; Lc 10:27; cf. Dt 6:5 LXX), del poder soberano de Dios que obra en Cristo y está disponible para los creyentes (Ef 1:19; 6:10; 2 Ts 1:9; 1 P 4:11), y de la doxología celestial que atribuye poder al Cordero (Ap 5:12; 7:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69626, 'spa', 'El sentido general de tener el poder, la capacidad o la aptitud para lograr algo', 'El sentido general de tener el poder, la capacidad o la aptitud para lograr algo. Es el uso más frecuente en todo el Nuevo Testamento, cubriendo situaciones desde la incapacidad de velar una hora en Getsemaní (Mt 26:40) hasta el fracaso de las cadenas para sujetar a un endemoniado (Mc 5:4). Se traduce directamente como ''poder'' en el sentido de capacidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69629, 'spa', 'Ser físicamente fuerte, sano o saludable, en contraste con estar enfermo', 'Ser físicamente fuerte, sano o saludable, en contraste con estar enfermo. El dicho de Jesús ''Los que están fuertes no tienen necesidad de médico'' (Mt 9:12 / Mc 2:17) usa ἰσχύω para denotar salud y robustez corporal, distinguiendo este sentido médico o físico de la noción más amplia de capacidad general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69630, 'spa', 'Aplicado a sujetos impersonales — leyes, oraciones, principios — con el signific', 'Aplicado a sujetos impersonales — leyes, oraciones, principios — con el significado de tener fuerza, validez o efectividad. La sal que ha perdido su sabor ''ya no sirve para nada'' (Mt 5:13), ni la circuncisión ni la incircuncisión ''vale'' nada sino la fe que obra por el amor (Gá 5:6), y un testamento ''tiene vigor'' después de la muerte (Heb 9:17). Santiago 5:16 afirma que la oración del justo ''tiene gran poder.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69641, 'spa', 'Prevalecer, vencer o imponerse sobre un adversario', 'Prevalecer, vencer o imponerse sobre un adversario. Hechos 19:16 ofrece el ejemplo más vívido: el hombre con el espíritu maligno ''prevaleció contra'' los siete hijos de Esceva, dominándolos físicamente. Hechos 19:20 lo usa de la palabra del Señor que ''prevalecía'' al extenderse, y Apocalipsis 12:8 describe al dragón que ''no prevaleció'' en el cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69648, 'spa', 'Quizás, tal vez', 'Jesús coloca esta palabra de esperanza incierta en boca del dueño de la viña, generando una trágica ironía dramática. El español ''quizás'' y el francés ''peut-être'' capturan la esperanza tentativa. El dueño cree que la presencia de su hijo podría provocar respeto donde los siervos fracasaron, pero la parábola revela que los líderes de Israel rechazaron incluso al mensajero final de Dios. Ese ''quizás'' manifiesta tanto la paciencia del dueño como la gravedad del rechazo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69649, 'spa', 'Península itálica', 'Nombre geográfico propio de la península itálica y el estado romano allí centrado. Las cuatro apariciones se relacionan con el desplazamiento de personas entre Italia y el Mediterráneo oriental: Aquila y Priscila parten de Italia bajo el edicto de Claudio (Hch 18:2), Pablo es enviado como prisionero a Italia (Hch 27:1), un barco alejandrino con rumbo a Italia lo transporta (Hch 27:6), y Hebreos 13:24 transmite saludos de los que están en Italia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69650, 'spa', 'Cohorte itálica', 'La especificación de Lucas sobre la cohorte itálica aporta tanto precisión histórica como significado teológico. Era una designación militar reconocible, y el español ''itálica'' preserva el adjetivo latino. Un centurión del corazón italiano de Roma, estacionado en la capital costera de Israel, recibe una visión que transforma la historia de la salvación: Dios no hace acepción de personas por su origen étnico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69651, 'spa', 'Región de Iturea', 'El marco cronológico de Lucas emplea fronteras políticas reconocibles para fechar la aparición profética de Juan. Al enumerar la tetrarquía de Felipe junto al reinado de Tiberio y la gobernación de Pilato, Lucas señala que el reino de Dios irrumpe en la historia concreta, en un momento específico y no en un tiempo mítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69653, 'spa', 'Pez', 'Pez: Un pez como criatura acuática literal, que aparece en narrativas evangélicas de provisión milagrosa, sustento diario e ilustraciones didácticas. Los milagros de alimentación (Mt 14:17, 19; 15:36) y la historia de la moneda en el pez (Mt 17:27) usan el término de manera concreta, al igual que la analogía del padre y el hijo (Mt 7:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69656, 'spa', 'Ejemplo a seguir', 'El sentido es consistentemente metafórico: seguir el camino, ejemplo o patrón de vida de alguien. Romanos presenta la fe de Abraham como huellas por las cuales caminar, su confianza en la promesa divina como modelo para todo creyente. Pablo defiende su conducta apelando a pisadas compartidas con Tito, un mismo patrón de ministerio. Pedro presenta el sufrimiento de Cristo como huellas que debemos seguir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69659, 'spa', 'Antepasado de Jesús', 'La genealogía de Lucas se extiende hacia atrás desde Jesús a través de antepasados desconocidos como Joanán, enraizando la encarnación en la historia de Israel. Aunque nada más sabemos de este individuo, su inclusión afirma que la humanidad de Jesús se remonta a personas reales, no a figuras míticas: el Verbo se hizo carne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69660, 'spa', 'Juan (nombre propio)', 'El nombre propio Ἰωάννης (del hebreo Yojanán, «YHWH es misericordioso»), aplicado a varias figuras del Nuevo Testamento. El principal es Juan el Bautista, quien preparó el camino para Jesús mediante la predicación y el bautismo (Mt 3:1-12; Jn 1:6-8). El segundo gran portador es Juan hijo de Zebedeo, apóstol, miembro del círculo íntimo de Jesús y autor tradicional del cuarto Evangelio (Mt 4:21; Mr 9:2; Hch 3:1). Otros incluyen a Juan Marcos y al padre de Pedro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69665, 'spa', 'Justo sufriente', 'Santiago invoca a Job no como modelo de silencio paciente, sino de fe persistente a través de una pérdida devastadora. La vindicación de Job no llegó mediante explicaciones sino mediante el encuentro: Dios le respondió no con razones sino con su presencia, y Santiago exhorta a los creyentes a confiar en esa misma compasión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69666, 'spa', 'Profeta del Espíritu', 'El sermón de Pedro en Pentecostés recurre a Joel para demostrar que la llegada dramática del Espíritu cumple la expectativa profética. El oráculo de Joel sobre los últimos días, «cuando derrame mi Espíritu sobre toda carne», se convierte en la lente apostólica para comprender Pentecostés: no una anomalía, sino el inicio de la era prometida de acceso universal al Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69667, 'spa', 'Antepasado de Jesús', 'Este antepasado poco conocido aparece solo en la genealogía de Lucas, que culmina no con Abraham sino con Adán, «hijo de Dios». Al incluir docenas de nombres olvidados, Lucas demuestra que la venida del Salvador requirió no solo reyes y profetas famosos, sino generaciones de personas comunes a través de las cuales Dios obró con paciencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69668, 'spa', 'Jonás (profeta del AT)', 'El profeta veterotestamentario Jonás (hebreo Yonah, ''paloma''), referido exclusivamente en el contexto del discurso de Jesús sobre ''la señal de Jonás''. Jesús traza un paralelo tipológico entre los tres días de Jonás en el gran pez y los tres días del Hijo del Hombre en la tierra (Mt 12:39-40; 16:4; Lc 11:29-30), y contrasta el arrepentimiento de los ninivitas con la incredulidad de su propia generación (Mt 12:41; Lc 11:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69671, 'spa', 'Antepasado de Jesús', 'Lucas incluye a Jorim entre los antepasados postexílicos, nombres que no aparecen en ninguna otra fuente bíblica o extrabíblica. La uniformidad en todas las lenguas refleja simple transliteración. Estos nombres desconocidos tienen peso teológico: atestiguan que el linaje mesiánico fluyó a través de personas reales durante siglos y que la redención divina involucró a los olvidados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69673, 'spa', 'Nombre propio compartido', 'Este sentido identifica el nombre propio compartido por dos hombres en el Evangelio de Marcos. El Josés de Marcos 6:3 es hermano de Jesús, mencionado junto a Jacobo, Judas y Simón, como evidencia que la audiencia de la sinagoga de Nazaret usó para cuestionar la autoridad de Jesús. El otro Josés (Marcos 15:40, 47) se distingue como hijo de una María diferente y hermano de Jacobo el menor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69674, 'spa', 'Jose (Ἰωσήφ)', 'La forma estandar Ἰωσήφ, que abarca a todos los portadores del nombre: el patriarca (Hch 7:9; Heb 11:22), el esposo de Maria (Mt 1:16-24), Jose de Arimatea (Mt 27:57), un hermano de Jesus (Mt 13:55) y dos antepasados en la genealogia de Lucas (Lc 3:24, 30). Todas las traducciones principales lo traducen de manera uniforme: espanol ''Jose'', frances e ingles ''Joseph'', aleman ''Josef''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69676, 'spa', 'Josec (Ἰωσήχ)', 'Una variante ortografica Ἰωσήχ que aparece unicamente en Lucas 3:26 para un antepasado de Jesus en la genealogia lucana. La tradicion textual conserva esta forma distinta, y las traducciones la reproducen como nombre separado (espanol ''Josec'', ingles ''Josech''), reflejando probablemente un original hebreo o arameo diferente o una variante escribal en la fuente genealogica de Lucas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69678, 'spa', 'Letra mínima simbólica', 'Jesús emplea la letra más pequeña imaginable para recalcar la permanencia de las Escrituras. Todas las lenguas conservan «iota» de forma idéntica, convirtiendo la letra en símbolo. Su argumento no es literalismo rígido sino cumplimiento integral: nada en la voluntad revelada de Dios es insignificante. El emparejamiento con «tilde» (κεραία) refuerza que las Escrituras permanecen íntegras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69679, 'spa', 'y yo / y a mí', 'Uso conectivo donde καί funciona como conjunción simple ''y'', enlazando la acción o identidad del hablante con la cláusula o participante anterior, sin énfasis especial de inclusión. Pasajes clave: Mt 11:28 (''Y yo os daré descanso''), Mt 16:18 (''Y yo te digo''). En español se traduce naturalmente como ''y yo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69680, 'spa', 'yo también / a mí también', 'Uso aditivo o intensivo donde καί funciona adverbialmente como ''también, incluso'', enfatizando la inclusión del hablante, su correspondencia o acción recíproca. Pasajes clave: Mt 10:32 (''Yo también le confesaré delante de mi Padre''), Mt 2:8 (''para que yo también vaya y le adore''). El español ''también yo'' explicita el matiz aditivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69689, 'spa', 'Conformidad comparativa', 'Mateo emplea καθά para vincular el dinero de Judas con el precedente profético. El español «como» y el francés «selon que» reflejan la conformidad implícita. El adverbio introduce la directriz divina respecto a las treinta piezas de plata, demostrando que incluso la compra del campo de sepultura por los sacerdotes cumple la predicción: la palabra de Dios gobierna la historia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69690, 'spa', 'Demolición o derribo', 'El sentido se centra en la destrucción o demolición, distinguiendo Pablo entre formas legítimas e ilegítimas. En 10:4 la demolición es positiva: las armas espirituales derriban razonamientos falsos y pretensiones contra el conocimiento de Dios. En 10:8 y 13:10 Pablo contrasta su autoridad divina para «edificación» (οἰκοδομή) frente al «derribo» (καθαίρεσις), negándose a usar la autoridad de modo destructivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69691, 'spa', 'Bajar físicamente', 'Bajar físicamente de una posición elevada, especialmente retirar un cuerpo de la cruz. Se usa cuatro veces para referirse al cuerpo crucificado de Jesús siendo bajado (Mr 15:36, 15:46; Lc 23:53; Hch 13:29). El español ''bajar/bajando/habiendo bajado'' marca consistentemente la acción física descendente y reverente. El uso repetido en los relatos de la Pasión confiere a este sentido su gravedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69692, 'spa', 'Derribar, demoler', 'Derribar, demoler o destruir estructuras, fortalezas o naciones. El rico insensato planea ''derribaré mis graneros'' (Lc 12:18); Pablo habla de ''destruir argumentos'' levantados contra el conocimiento de Dios (2 Co 10:5); Hechos 13:19 recuerda que Dios destruyó siete naciones. El español pasa del físico ''bajar'' al destructivo ''derribar/destruir'', y el rango abarca desde edificios literales hasta fortificaciones metafóricas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69697, 'spa', 'Deponer, derrocar', 'Deponer o derrocar a alguien de una posición de poder y autoridad. En el Magnificat, María proclama que Dios ''derribó de sus tronos a los poderosos'' (Lc 1:52). El español ''derribó'' captura el destronamiento contundente, mientras que el mismo verbo usado para bajar físicamente y para demoler estructuras ahora expresa la inversión divina de las jerarquías sociales: los poderosos humillados, los humildes exaltados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69699, 'spa', 'Poda purificadora', 'El discurso de Jesús sobre la vid y los pámpanos convierte la poda en imagen de la disciplina santificadora. El español «limpia» y el francés «émonder» captan la remoción de obstáculos. La poda divina incluye pruebas y eliminación de lo cómodo pero improductivo. El verbo comparte raíz con καθαρός (limpio), vinculando fecundidad con pureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69700, 'spa', 'Partícula comparativa que significa «así como, de la misma manera que, tal como»', 'Partícula comparativa que significa «así como, de la misma manera que, tal como», usada para introducir una analogía o establecer un punto de correspondencia. Aparece trece veces en el corpus paulino y en otros lugares para estructurar argumentos teológicos mediante comparación: como David pronuncia bienaventuranza (Ro 4:6), como el cuerpo tiene muchos miembros (Ro 12:4; 1 Co 12:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69701, 'spa', 'Prenderse con fuerza', 'La elección de καθάπτω por Lucas enfatiza la agresiva fijación de la víbora en la mano de Pablo tras ser avivada por el calor. El español «se prendió» capta la fuerza reflexiva. La reacción de los isleños y su cambio al ver que Pablo no sufre daño demuestran cómo Dios transforma los ataques hostiles en testimonios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69702, 'spa', 'Limpiar fisica o ritualmente', 'Hacer fisica o ritualmente limpio eliminando la impureza, especialmente sanando leprosos y declarando alimentos o utensilios puros. Jesus ordena a los leprosos ''!Se limpio!'' (Mt 8:2-3; Lc 17:14) y los apostoles reciben el mandato de ''limpiar leprosos'' como senal del reino (Mt 10:8). Marcos 7:19 extiende el uso a la declaracion de que todos los alimentos son limpios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69705, 'spa', 'Purificar moral o espiritualmente', 'Purificar del pecado, la contaminacion moral o la impureza espiritual, con Dios, Cristo o su sangre como agente de limpieza. Dios purifico los corazones de los gentiles por la fe (Hch 15:9), Cristo se dio a si mismo para ''purificar para si un pueblo'' (Tit 2:14), y su sangre ''nos limpia de todo pecado'' (1 Jn 1:7; cf. Heb 9:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69724, 'spa', 'Purificación ritual', 'Purificación, limpieza ceremonial: el acto ritual de llegar a ser o ser declarado ritualmente limpio. El vocablo se vincula directamente con las abluciones y ofrendas prescritas por la Torá. Jesús ordena a los leprosos sanados completar su purificación mosaica (Mr 1:44; Lc 5:14). Las tinajas de agua en Caná sirven para ''los ritos de purificación judíos'' (Jn 2:6), y una disputa sobre purificación enmarca el último testimonio del Bautista (Jn 3:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69728, 'spa', 'Limpio o puro en sentidos ritual, moral o físico', 'Limpio o puro en sentidos ritual, moral o físico. Moralmente, describe el corazón orientado hacia Dios (Mt 5:8) y la conciencia libre de contaminación (1 Ti 1:5; 3:9; 2 Ti 1:3; Tit 1:15). Ritualmente, Jesús lo redefine: el lavamiento exterior importa menos que la transformación interior (Mt 23:26; Jn 13:10-11; 15:3). Pablo lo usa para la inocencia apostólica ante Dios (Hch 18:6; 20:26). Físicamente, Apocalipsis lo aplica al esplendor celestial: ''lino fino, resplandeciente y puro'' (Ap 15:6; 19:8, 14; 21:18, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69734, 'spa', 'Pureza ritual levítica', 'Hebreos emplea καθαρότης para describir la eficacia limitada pero real de las purificaciones levíticas. El argumento avanza de lo menor a lo mayor: si los sacrificios podían restaurar la pureza ceremonial, cuánto más el sacrificio de Cristo purificará la conciencia de obras muertas. Los ritos antiguos prefiguraban la limpieza interior definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69735, 'spa', 'Asiento y cátedra', 'El sentido abarca asientos físicos y posiciones simbólicas. Los asientos de los mercaderes del templo eran mobiliario literal, parte del aparato comercial que Jesús derribó para restaurar la casa de oración. La cátedra de Moisés (Mateo 23:2) era probablemente tanto un asiento real en la sinagoga desde el cual se leía la Torá, como una metáfora de la posición de enseñanza autoritativa que ocupaban escribas y fariseos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69736, 'spa', 'Sentarse, estar sentado', 'Sentarse, tomar asiento o permanecer en posición sentada: verbo de postura física que indica tanto la acción de acomodarse como un estado sostenido. En Mt 26:55 Jesús recuerda a sus captores que se sentaba cada día a enseñar en el templo. En Lc 2:46 el Jesús de doce años es hallado sentado entre los maestros. Junto al pozo de Jacob, Jesús se sentó fatigado del camino (Jn 4:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69742, 'spa', 'En orden sucesivo', 'En orden, sucesivamente, uno tras otro. Denota disposición ordenada o progresión secuencial. Lucas lo usa para describir su método narrativo de escribir los acontecimientos «por orden» (Luke 1:3), el viaje sistemático de Jesús por las ciudades (Luke 8:1), el relato secuencial de Pedro (Acts 11:4), los profetas desde Samuel hablando «sucesivamente» (Acts 3:24) y el itinerario ordenado de Pablo por las regiones (Acts 18:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69743, 'spa', 'Estar en estado de sueño natural y físico', 'Estar en estado de sueño natural y físico. Mateo 8:24 describe a Jesús durmiendo durante la tormenta; Mateo 26:40-43 muestra a los discípulos durmiendo en Getsemaní por agotamiento. Marcos 4:38 y Mateo 13:25 describen igualmente el dormir literal, el descanso corporal ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69745, 'spa', 'Dormir en sentido figurado, denotando letargo espiritual, complacencia moral, de', 'Dormir en sentido figurado, denotando letargo espiritual, complacencia moral, desatención a los propósitos de Dios, o la muerte como eufemismo. La parábola de las diez vírgenes (Mateo 25:5) lo usa para la espera negligente; 1 Tesalonicenses 5:6 contrasta el dormir con la vigilancia; Marcos 5:39 puede implicar la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69758, 'spa', 'sentarse en trono, reinar', 'Sentarse en trono, ocupar una posición de autoridad, gobierno o juicio (55 ocurrencias). Es el sentido dominante en el NT: Cristo sentado a la diestra de Dios (Mt 26:64; Ap 4:2), Dios entronizado en el cielo (Ap 4:9-10), gobernantes en sillas de juicio y los jinetes apocalípticos del Apocalipsis. Se emplean registros elevados en diversas lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69759, 'spa', 'sentarse físicamente', 'Sentarse o estar sentado en sentido literal y físico: en el suelo, a la mesa, en un asiento o junto al camino (26 ocurrencias). Jesús se sienta junto al mar para enseñar (Mt 13:1-2), Pedro se sienta en el patio (Mt 26:58), los ciegos se sientan junto al camino (Mt 20:30). Se distingue del sentido 1 por la ausencia de autoridad o función oficial: es postura corporal sin connotación de estatus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69763, 'spa', 'habitar, residir', 'Habitar, residir o morar en un lugar o condición, usado metafóricamente para personas asentadas en una región o estado (10 ocurrencias). Mt 4:16 cita a Isaías: ''el pueblo sentado en tinieblas vio gran luz'', donde ''sentado'' significa permanencia prolongada, no postura física. Lc 21:35 extiende esto a todos los que ''están sentados sobre la faz de la tierra'', es decir, que la habitan como residentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69782, 'spa', 'Distribución cotidiana', 'Lucas resalta la naturaleza rutinaria del programa de asistencia a viudas mediante καθημερινός. La «distribución diaria» era lo suficientemente importante como para requerir administración dedicada y culturalmente significativa al punto de que la inequidad percibida amenazaba la unidad eclesial. La solución apostólica —nombrar hombres llenos del Espíritu— sentó un precedente para la organización ministerial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69783, 'spa', 'Sentarse, tomar asiento', 'El sentido intransitivo basico: sentarse o asumir una posicion sentada. Jesus se sienta para ensenar (Mt 5:1), se sienta junto al mar (Mt 13:48) y promete a los discipulos que se sentaran en tronos juzgando a las doce tribus (Mt 19:28). La postura sentada conlleva autoridad en el mundo antiguo: un juez, un maestro, un rey se sienta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69791, 'spa', 'Sentar, hacer sentar', 'El sentido transitivo o causativo: sentar a otra persona, hacer que otro se siente. Dios ''sento'' (ἐκάθισεν) a Cristo a su diestra en los lugares celestiales (Ef 1:20). En Hechos 2:30, David sabia que Dios ''sentaria'' a uno de sus descendientes en su trono. Pablo pregunta en 1 Corintios 6:4 por que los corintios ''sientan'' como jueces a los de menor estima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69793, 'spa', 'Permanecer, quedarse', 'Un sentido extendido que significa permanecer, quedarse o establecerse en un lugar, donde la duracion es lo importante y no la postura. Jesus instruye a los discipulos a ''quedarse en la ciudad'' hasta que venga el poder (Lc 24:49), y Pablo ''permanecio'' en Corinto un ano y seis meses ensenando (Hch 18:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69801, 'spa', 'Hacer descender, bajar', 'Hacer descender o bajar algo desde una posición más alta a una más baja, normalmente mediante cuerda, sábana o canasto. En Lc 5:19 describe el descenso del paralítico a través de las tejas; en Hch 9:25 Pablo es descolgado en un canasto; en Hch 10:11 y 11:5 Pedro ve un gran lienzo que baja del cielo. La evidencia multilingüe apunta uniformemente a un movimiento descendente controlado e intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69802, 'spa', 'El sentido dominante de designar, establecer o constituir a alguien en un cargo,', 'El sentido dominante de designar, establecer o constituir a alguien en un cargo, oficio o posición de autoridad, que abarca 20 de las 22 apariciones. En las parábolas de Mateo 24:45-47 y 25:21-23, el señor designa siervos sobre sus posesiones. Tito 1:5 encarga establecer ancianos en cada ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69810, 'spa', 'Una única aparición en Hechos 17', 'Una única aparición en Hechos 17:15 que conserva el sentido físico-espacial de conducir o escoltar a una persona hasta un destino. Los que conducían a Pablo lo llevaron hasta Atenas. Este uso concreto conecta directamente con el significado clásico de καθίστημι: llevar a alguien a un lugar determinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69813, 'spa', 'Un sentido posicional poco frecuente en Santiago 3', 'Un sentido posicional poco frecuente en Santiago 3:6, donde la lengua queda establecida entre los miembros del cuerpo como el mundo de la injusticia. Aquí el verbo describe colocación o establecimiento físico en una ubicación, no nombramiento a un oficio, preservando la raíz espacial del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69816, 'spa', 'Según, en la medida', 'En la medida en que, según, en cuanto: expresa proporción o correspondencia entre dos estados de cosas. En Ro 8:26 califica la insuficiencia humana en la oración; en 2 Co 8:12 establece la medida de la ofrenda aceptable; en 1 Pe 4:13 conecta el sufrimiento presente con la alegría futura. El término no indica mera condición, sino una relación graduada de correspondencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69817, 'spa', 'Prohibición total', 'El uso de καθόλου por parte del Sanedrín revela su intención de silenciar completamente al cristianismo. Sin embargo, la prohibición total resultó inaplicable contra hombres que respondían a una autoridad superior. Pedro y Juan establecieron el principio de que ninguna autoridad humana puede impedir la proclamación del evangelio cuando Dios ha comisionado a sus testigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69818, 'spa', 'Armado por completo', 'Jesús emplea καθοπλίζομαι para enfatizar la aparente seguridad de Satanás: completamente armado y custodiando su dominio. No obstante, el armamento exhaustivo no puede resistir un poder superior. La victoria de Cristo no es una contienda reñida, sino el triunfo del más fuerte sobre el fuerte, asegurando a los creyentes que la batalla cósmica ya fue decidida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69819, 'spa', 'Percepción clara', 'El uso paulino de καθοράω fundamenta la responsabilidad humana en la percepción nítida de la realidad divina a través de la creación. El poder eterno y la naturaleza divina de Dios no están ocultos sino que se manifiestan a quienes observan rectamente. La voz pasiva sugiere percepción continua y accesible que hace inexcusable la incredulidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69820, 'spa', 'Porque, por cuanto', 'Conjunción causal que significa ''porque'' o ''por cuanto'', introduciendo el fundamento o razón de una afirmación precedente. En Lc 1:7 explica por qué Elisabet no tenía hijos (''por cuanto Elisabet era estéril''); en Hch 2:24 ofrece la razón teológica de la resurrección (''porque no era posible que la muerte lo retuviera''). En español, ''por cuanto'' y ''puesto que'' subrayan la base causal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69821, 'spa', 'Según, conforme a', 'Conjunción proporcional o comparativa que significa ''según'' o ''conforme a'', indicando el grado o la manera en que algo se realiza. En Hch 2:45 y 4:35, los bienes se repartían ''según la necesidad de cada uno''. El español ''según'' capta con precisión este sentido proporcional, distinguiéndolo del uso puramente causal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69822, 'spa', 'así como, tal como', 'Conjunción comparativa que significa «así como», «tal como» o «como» — introduce un modelo de comparación, un patrón cumplido o una base para la acción. La unanimidad interlingüística es notable: «como» (esp.), comme (fr.), wie (al.) convergen en una única función comparativa. Omnipresente en fórmulas de cumplimiento («así como está escrito», Mt 26:24), exhortaciones éticas («amaos unos a otros como yo os he amado», Jn 13:34) y fundamentaciones teológicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69824, 'spa', 'cómo', 'Interrogativo o declarativo «cómo», que introduce la manera o el modo en que algo sucedió, en lugar de una comparación. En Hch 15:14, Santiago dice que Simeón describió «cómo» (καθώς) Dios visitó primero a los gentiles. El español distingue claramente este sentido mediante «cómo» (con tilde, marcando fuerza interrogativa), mientras que el francés y el alemán mantienen comme/wie, que son ambiguos entre el sentido comparativo y el de modo. Este uso infrecuente preserva un rasgo del griego clásico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69825, 'spa', 'conjunción copulativa «y»', 'La conjunción copulativa «y», que une palabras, frases y cláusulas en secuencia. Conectivo por defecto de la prosa griega. Cada idioma lo traduce con su conjunción básica: español «y», francés «et». Más de 8,300 de las 9,083 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69826, 'spa', 'uso adverbial «también»', 'El uso adverbial o ascensivo que significa «también, aun, igualmente», añadiendo énfasis o un elemento inesperado. El español lo traduce distintivamente como «también». Se encuentra en Mat 5:39-40, Mat 5:46. Aproximadamente 771 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69827, 'spa', 'Caifás (sumo sacerdote)', 'El sumo sacerdote judío Caifás (de origen arameo, posiblemente ''roca'' o ''depresión''), quien ejerció el cargo durante el ministerio público de Jesús, su juicio y el período de la iglesia primitiva. Aparece en la conspiración para arrestar a Jesús (Mt 26:3), el juicio nocturno (Mt 26:57; Jn 18:13-14, 24, 28), como marcador cronológico junto a Anás (Lc 3:2), y en su profecía involuntaria sobre la muerte sustitutoria de Jesús (Jn 11:49-50).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69829, 'spa', 'Figura del Génesis', 'El único sentido identifica al personaje de Génesis, invocado como el malhechor paradigmático. Hebreos contrasta su ofrenda rechazada con la de Abel aceptada. Primera Juan lo señala explícitamente como «del maligno», vinculando el fratricidio con un origen satánico y explicando su motivo: sus obras eran malas mientras que las de su hermano eran justas. Judas lo convierte en epónimo de un camino de rebeldía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69831, 'spa', 'Nuevo, fresco, sin precedente', 'Cualitativamente nuevo o sin precedente en su naturaleza, no meramente reciente en el tiempo. La distincion καινός/νέος tiene carga teologica: καινός senala la renovacion escatologica — nuevo pacto (Lc 22:20; Heb 8:13), nueva creacion (2 Co 5:17), mandamiento nuevo (Jn 13:34), nueva Jerusalen (Ap 21:2). El espanol ''nuevo/nueva'' lo traduce, aunque no preserva el contraste καινός/νέος.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69838, 'spa', 'Aunque, a pesar de', 'Aunque, a pesar de que: partícula concesiva empleada típicamente con un participio para expresar un contraste inesperado. En Heb 5:8 introduce la profunda paradoja de que Cristo ''aunque era Hijo'' aprendió obediencia por medio del sufrimiento. En Heb 7:5 y 12:17 señala circunstancias concesivas. Pablo la usa para reconocer sus credenciales antes de descartarlas (Phil 3:4), y 2 Pet 1:12 la emplea para matizar el conocimiento previo de los lectores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69839, 'spa', 'tiempo determinado', 'Sentido dominante con unas 80 ocurrencias: designa un punto o período definido, señalado o decisivo en el tiempo, a menudo dentro del plan redentor de Dios. Abarca el tiempo de la cosecha (Mt 13:30), el tiempo de la visitación (Lc 19:44), el tiempo presente (Ro 3:26; 8:18) y los momentos escatológicos (Mt 8:29, ''antes de tiempo''). Se traduce consistentemente como ''tiempo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69843, 'spa', 'temporada o época', 'Un grupo reducido (unas 3 ocurrencias) se estrecha al sentido de temporada o época: una era, edad o estación natural definida. En Hch 14:17 Dios dio ''tiempos fructíferos''; Gá 4:10 advierte contra observar ''tiempos y estaciones''; 1 Ts 5:1 empareja καιροί con χρόνοι para abarcar todo el horizonte temporal. El español ''épocas'' marca este marco temporal más amplio y prolongado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69846, 'spa', 'tiempo oportuno', 'Tres ocurrencias destacan el carácter oportuno o propicio del momento: la ventana de acción favorable. En Lc 4:13, el diablo se aparta ''hasta tiempo oportuno'' (ἄχρι καιροῦ); Lc 20:10 refiere enviar un siervo ''a su tiempo'' (es decir, el momento adecuado para recoger); Hch 1:7 habla de tiempos que el Padre ha fijado con su propia autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69850, 'spa', 'El título y nombre propio Καῖσαρ (César) para el emperador romano, que porta tan', 'El título y nombre propio Καῖσαρ (César) para el emperador romano, que porta tanto autoridad política como tensión teológica en el NT. La controversia sinóptica sobre el tributo (Mateo 22:17-21) plantea la cuestión de la doble lealtad a Dios y al imperio. En Hechos, la apelación de Pablo al César (Hechos 25:11) invoca el derecho legal de la ciudadanía romana, trasladando la narrativa a Roma misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69856, 'spa', 'Cesarea (topónimo)', 'Cesarea (topónimo): El topónimo Cesarea, que designa ya sea Cesarea Marítima en la costa del Mediterráneo o Cesarea de Filipo cerca del monte Hermón. La ciudad costera domina Hechos como centro administrativo romano donde Cornelio se convierte (Hch 10:1, 24; 11:11), Pablo es encarcelado y juzgado (Hch 23:23, 33; 25:1, 4, 6, 13) y Felipe el evangelista reside (Hch 8:40; 21:8, 16). Cesarea de Filipo aparece solo en el contexto de la confesión de Pedro (Mt 16:13; Mc 8:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69859, 'spa', 'Concesion contrastiva', 'Juan emplea καίτοι para corregir la impresion de que Jesus realizaba personalmente los bautismos. El espanol ''aunque'' capta bien la fuerza concesiva. Los fariseos oyeron que Jesus hacia y bautizaba mas discipulos que Juan, pero el evangelista aclara que eran los discipulos de Jesus, no Jesus mismo, quienes efectuaban los bautismos. Este detalle distingue el ministerio de Jesus del de Juan el Bautista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69860, 'spa', 'Arder, estar en llamas — estado intransitivo o pasivo de ser consumido por el fu', 'Arder, estar en llamas — estado intransitivo o pasivo de ser consumido por el fuego o irradiar llamas, ya sea fuego literal o ardor metafórico. Este sentido dominante (10 apariciones) abarca desde lo práctico hasta lo apocalíptico: lámparas que arden en espera (Lc 12:35), los corazones de los discípulos de Emaús ''ardiendo dentro'' mientras Jesús exponía las Escrituras (Lc 24:32), Juan el Bautista como ''la lámpara que ardía y alumbraba'' (Jn 5:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69863, 'spa', 'Encender, prender — acción transitiva y causativa de producir fuego o luz', 'Encender, prender — acción transitiva y causativa de producir fuego o luz. Solo 1 aparición clara en el NT: Mt 5:15, donde Jesús observa que las personas ''encienden una lámpara'' (καίουσιν λύχνον) no para esconderla bajo un almud, sino para ponerla en el candelero y que alumbre a toda la casa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69865, 'spa', 'Y allí — sentido narrativo-espacial estándar', 'Y allí — sentido narrativo-espacial estándar: ''y allí,'' ''en aquel lugar,'' vinculando una nueva acción o estado a un lugar previamente mencionado. Aparece nueve veces conectando eventos con sus escenarios a lo largo de los Evangelios y Hechos. Jesús instruye a los discípulos sobre la reconciliación ''allí'' ante el altar (Mt 5:23), les ordena permanecer ''allí'' en cualquier ciudad que entren (Mt 10:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69867, 'spa', 'También allí — sentido aditivo-locativo', 'También allí — sentido aditivo-locativo: ''también allí,'' ''allí también,'' enfatizando que algo se extiende o se repite en un lugar más allá de lo esperado. Usado en Hechos 17:13, donde agitadores hostiles de Tesalónica persiguen a Pablo hasta Berea. El matiz de ''incluso allí'' destaca que el hostigamiento no se limita a una sola ciudad, sino que sigue ''también allí.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69868, 'spa', 'Y de allí — adverbio conectivo que significa ''y de allí / y desde allí,'' usado p', 'Y de allí — adverbio conectivo que significa ''y de allí / y desde allí,'' usado para avanzar la narración marcando la partida de un lugar previamente mencionado. Encadena segmentos de itinerario en los Evangelios — Jesús desplazándose por Galilea (Mc 9:30; 10:1) — y especialmente en Hechos para las rutas misioneras de Pablo a través de ciudades de Asia Menor y Grecia (Hch 14:26; 16:12; 20:15; 21:1; 27:4; 28:15). Esteban lo usa al referirse al traslado de Abraham.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69869, 'spa', 'Uso aditivo o enfático que subraya que el referente participa del mismo predicad', 'Uso aditivo o enfático que subraya que el referente participa del mismo predicado o condición: aquel también, aquellos también, él/ellos igualmente. Juan 10:16 lo usa de las otras ovejas que también deben ser traídas; Juan 6:57 declara que quien come de Cristo también vivirá. Abarca 11 apariciones incluyendo Juan 14:12 y 17:24.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69871, 'spa', 'Uso conjuntivo simple que coordina un referente adicional en la secuencia narrat', 'Uso conjuntivo simple que coordina un referente adicional en la secuencia narrativa: y aquel, y aquellos, sin fuerte énfasis aditivo. Marcos 12:4-5 lo emplea para encadenar sucesivos siervos enviados a la viña; Mateo 15:18 conecta lo que sale de la boca con su origen. Refleja una conjunción directa más que una inclusión enfática, con 11 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69881, 'spa', 'Malicia, maldad — maldad moral, malicia o perversidad como disposición arraigada', 'Malicia, maldad — maldad moral, malicia o perversidad como disposición arraigada del carácter. Este es el uso dominante en el NT, apareciendo en listas de vicios junto a la envidia, el engaño y la calumnia (Ro 1:29, Ef 4:31, Col 3:8). Pablo la contrasta con la sinceridad en 1 Co 5:8 (''la levadura de malicia y maldad''), y en 1 Co 14:20 insta a los creyentes a ser ''niños en la malicia'' — inocentes de intención maligna. La evidencia interlingüística muestra consistencia amplia: español maldad, alemán Bosheit, francés méchanceté y árabe شَرّ convergen en el campo semántico de la malicia deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69884, 'spa', 'Problema, dificultad — problema, angustia o dificultad como realidad experiencia', 'Problema, dificultad — problema, angustia o dificultad como realidad experiencial más que como cualidad moral. Atestiguado únicamente en Mateo 6:34, donde Jesús enseña ''basta a cada día su propio mal (κακία)''. Aquí la palabra denota las cargas y dificultades que trae la vida, no la maldad moral. Varias traducciones captan esta distinción: inglés trouble en lugar de malice, español mal (cosa mala genérica) en vez de maldad, señalando un matiz experiencial distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69887, 'spa', 'Malevolencia deliberada', 'Pablo enumera κακοήθεια entre los vicios que caracterizan a la humanidad bajo la ira de Dios. La ''malignidad'' en espanol capta bien la mala intencion deliberada. No se trata de violencia impulsiva sino de malicia fria: la mentalidad que trama el dano, interpreta al projimo con la peor intencion y se regocija en la maldad. Refleja un corazon no solo alejado de Dios, sino activamente hostil hacia los demas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69888, 'spa', 'Maldecir e injuriar', 'Hablar mal de alguien, injuriarlo o maldecirlo, frecuentemente con connotación de maldición o difamación. En Mt 15:4 y Mc 7:10, Jesús cita el mandato de la Torá contra maldecir a los padres, donde la palabra lleva peso legal y de pacto. En Mc 9:39 Jesús señala que nadie que haga un milagro en su nombre hablará mal de él fácilmente. En Hch 19:9 describe el vituperio público contra la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69889, 'spa', 'Padecimiento paciente', 'Santiago empareja κακοπάθεια con la paciencia (μακροθυμία), convirtiendo a los profetas en modelos de resistencia fiel bajo la adversidad. El espanol ''sufrimiento'' capta bien la experiencia dolorosa. Los profetas proclamaron la palabra de Dios y con frecuencia sufrieron por ello: rechazo, persecucion, a veces la muerte. Su ejemplo ensena a los creyentes a esperar dificultades y a soportarlas con paciencia, confiando en la fidelidad de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69890, 'spa', 'Soportar penalidades', 'El sentido enfatiza la resistencia ante la adversidad, particularmente en el ministerio y la vida cristiana. Pablo lo modela personalmente —sufriendo cadenas por el evangelio— y ordena a Timoteo aceptarlo como parte del servicio fiel. La metáfora del soldado (2 Timoteo 2:3-4) presenta la resistencia ante las dificultades como esencial para el discipulado. Santiago lo aplica más ampliamente a cualquier padecimiento, con la oración como respuesta prescrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69891, 'spa', 'Hacer el mal', 'Obrar el mal o actuar de manera dañina, usado en contraste moral y ético con hacer el bien. Mc 3:4 y Lc 6:9 enmarcan la controversia sabática: ¿es lícito hacer el bien o hacer el mal? En 1 Pe 3:17 el sufrimiento por hacer el bien se opone al sufrimiento por obrar mal. En 3 Jn 1:11 se insta a imitar lo bueno y no lo malo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69892, 'spa', 'Malhechor', 'El sentido identifica a quienes hacen el mal o causan daño, mientras Pedro navega la tensión entre la falsa acusación y la maldad real. En 2:12 los cristianos son calumniados «como malhechores» a pesar de vivir rectamente; la acusación es falsa pero debe responderse con conducta ejemplar. En 2:14 el término describe a criminales genuinos que el gobierno justamente castiga. En 4:15 Pedro advierte que los creyentes nunca deben merecer tal calificativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69893, 'spa', 'mal, maldad (abstracto)', 'El concepto sustantivado o abstracto de mal y maldad moral, el uso dominante en el NT. Jesús señala los malos pensamientos (Mr 7:21) como brotando del corazón, y Pablo advierte que las malas compañías corrompen las buenas costumbres (1 Co 15:33). En todas las lenguas este sentido toma términos de peso moral: español ''mal'', francés ''mauvais'', alemán ''böse''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69899, 'spa', 'personas malvadas', 'Masculino plural sustantivado que identifica a personas malvadas, aquellos que encarnan la maldad. El dueño de la parábola de Jesús ''destruirá miserablemente a aquellos malvados'' (Mt 21:41), y la iglesia de Éfeso probó a quienes se decían apóstoles y los halló falsos (Ap 2:2). El español ''malos'' porta la misma fuerza personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69904, 'spa', 'malo, dañino, nocivo', 'Dañino, perjudicial o de mala calidad, con énfasis en el efecto nocivo más que en el carácter moral. En Lc 16:25 Lázaro recibió ''cosas malas'' durante su vida, no moralmente perversas sino dolorosas y desfavorables. El español ''malas'' y el alemán ''schlecht'' a veces se inclinan hacia este registro no moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69911, 'spa', 'Malhechor judicial', 'Criminal o malhechor en sentido judicial, alguien formalmente reconocido como autor de maldad. La estructura compuesta del griego (κακός + ἔργον, ''obrador de mal'') se preserva en el español malhechor. En Lc 23:32-33, 39, designa a los dos hombres crucificados con Jesús, con todo el peso de la condena legal. En 2 Ti 2:9, Pablo sufre prisión ''como criminal'' por predicar el evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69913, 'spa', 'Maltratar, oprimir', 'Maltratar, dañar u oprimir, infligiendo sufrimiento o injusticia. En el NT aparece solo en Hechos, trazando la persecución a lo largo de la historia salvífica: la opresión egipcia (Hch 7:6, 19), el ataque de Herodes a la iglesia (Hch 12:1), la hostilidad en Iconio (Hch 14:2) y la promesa protectora de Dios a Pablo (Hch 18:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69919, 'spa', 'Mal, gravemente (enfermedad)', 'Mal, gravemente (enfermedad): Adverbio que describe la gravedad de una aflicción física: ''mal, gravemente enfermo''. Este es el uso dominante en el NT, apareciendo doce veces casi exclusivamente en las narrativas sinópticas de sanación. La frase formulaica κακῶς ἔχοντες (''los que están mal'', es decir, los gravemente enfermos) se repite en Mt 4:24, 8:16, 9:12, 14:35 y Mc 1:32.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69921, 'spa', 'Incorrectamente, perversamente', 'Incorrectamente, perversamente: Adverbio de cualidad moral que describe habla o conducta incorrecta: ''incorrectamente, perversamente, con mala intención''. En Jn 18:23 Jesús lo usa respecto al habla (''si hablé mal''), en Hch 23:5 Pablo es reprendido por hablar mal del sumo sacerdote, en Stg 4:3 los creyentes ''piden mal'', y en Mt 21:41 los labradores malvados serán destruidos ''miserablemente'' (κακοὺς κακῶς).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69924, 'spa', 'Opresion sistematica', 'El discurso de Esteban emplea κάκωσις para caracterizar la opresion de Egipto sobre Israel, haciendose eco de Exodo 3:7. El espanol ''afliccion'' y ''maltrato'' captan el abuso involucrado. Dios declara: ''He visto el maltrato de mi pueblo''; no es indiferente a la injusticia. La narrativa del exodo establece un patron: Dios escucha el clamor de los oprimidos y los libera, juzgando a quienes abusan de su poder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69925, 'spa', 'Material combustible', 'Pablo usa καλάμη como el material de construccion mas inutil imaginable: rastrojo seco que se enciende al instante. El espanol ''paja'' transmite bien la idea. La metafora advierte a los ministros que no toda obra realizada sobre el fundamento de Cristo tiene el mismo valor. La ensenanza que solo entretiene o halaga, el ministerio que busca aprobacion humana en lugar de transformacion espiritual, sera consumido como paja en el dia del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69926, 'spa', 'Caña (planta o vara)', 'Caña (planta o vara): la caña como planta viva o como vara/bastón fabricado de ella. En Mt 11:7 y Lc 7:24, Jesús usa la imagen de una caña mecida por el viento como metáfora de la inconstancia. Mt 12:20 cita a Isaías: «la caña cascada no quebrará», evocando ternura hacia lo frágil. En la crucifixión, una caña sirvió tanto como cetro burlesco (Mt 27:29) como palo para levantar una esponja con vinagre (Mt 27:48; Mr 15:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69929, 'spa', 'Pluma (instrumento de escritura)', 'Pluma (instrumento de escritura): una pluma de caña, instrumento de escritura fabricado cortando y afilando un tallo de caña hasta formar una punta. Este sentido especializado aparece solo en 3 Jn 1:13, donde el anciano escribe: «Tenía muchas cosas que escribirte, pero no quiero escribírtelas con pluma y tinta». El mismo objeto físico — la caña — hace la transición de planta silvestre a herramienta de escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69930, 'spa', 'nombrar, designar', 'Dar un nombre o título a alguien, o llevar una designación. Es la acepción más frecuente con 67 apariciones, abarcando tanto el nombramiento activo («llamarás su nombre Jesús», Mt 1:21) como el pasivo («será llamado nazareno», Mt 2:23). El español llamado y el francés appelé convergen en la designación más que en la convocatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69932, 'spa', 'convocar, hacer venir', 'Convocar o llamar a alguien para que se acerque: el sentido transitivo básico de dirigir a una persona hacia el hablante, con 28 apariciones en contextos narrativos. Herodes convocando a los magos (Mt 2:7), Jesús llamando a los discípulos (Mt 4:21), mandando llamar a siervos o multitudes. El español llamar a y el francés appeler en su sentido directivo captan bien este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69934, 'spa', 'llamar a la salvación', 'Llamar o elegir a alguien para un propósito divino, la salvación o la vocación espiritual, siendo Dios el agente que llama a los creyentes a la fe, la santidad o el servicio. Con 36 apariciones, predominantemente paulinas y epistolares, este sentido teologizado genera el sustantivo κλῆσις («llamamiento/vocación») y el adjetivo κλητός («llamado»). Romanos 8:30 lo encadena en la secuencia áurea: predestinar, llamar, justificar, glorificar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69940, 'spa', 'invitar a un evento', 'Invitar a alguien a una fiesta, banquete o reunión social. Se distingue nítidamente por el uso de invitar/invitado en español y por el coreano 초대하다. Las 17 apariciones se concentran en las parábolas: el banquete de bodas (Mt 22:3-4, 8), la gran cena (Lc 14:7-24) y Simón el fariseo. Es el sentido de hospitalidad concreta, no de mera convocatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69985, 'spa', 'Olivo cultivado', 'Pablo emplea καλλιέλαιος para resaltar la superioridad de la posición pactual de Israel: el árbol cultivado y cuidado en el que los gentiles silvestres son injertados. El español ''buen olivo'' transmite esa cualidad domesticada. El injerto antinatural advierte a los cristianos gentiles contra la arrogancia: han sido incluidos por gracia, no por mérito, en un árbol que no plantaron.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69986, 'spa', 'Mejor, más apropiadamente', 'Pablo usa κάλλιον para afirmar la legitimidad de su apelación al César. El español ''mejor'' capta bien la fuerza comparativa. Pablo no huía de la justicia sino que la buscaba: reconocía que un juicio en Jerusalén, donde las autoridades judías procuraban su muerte, no sería ni justo ni seguro. Su ciudadanía romana le daba derecho a la jurisdicción imperial, y ejerce ese derecho con firmeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69987, 'spa', 'Maestras de lo bueno', 'Pablo emplea καλοδιδάσκαλος como parte de sus instrucciones para el orden eclesial en Creta. El español ''maestras de lo bueno'' preserva la estructura compuesta del término. El contexto muestra que las ''cosas buenas'' incluyen dominio propio, pureza, administración del hogar, bondad y sumisión: virtudes que adornan el evangelio. Este modelo de discipulado intergeneracional asigna un papel formativo especial a las mujeres mayores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69988, 'spa', 'Hacer el bien', 'Pablo usa καλοποιέω para animar a un esfuerzo moral sostenido. El español ''hacer el bien'' capta la idea de virtud activa. El peligro que Pablo aborda no es el fracaso moral sino la fatiga moral: la tentación de dejar de esforzarse, de bajar los estándares, de abandonar la vida fiel cuando parece infructuosa. Frente a esto, Pablo ordena resiliencia: seguir haciendo el bien incluso cuando resulta costoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69990, 'spa', 'bueno, recto, excelente', 'Moralmente bueno, encomiable, excelente o de calidad superior: se aplica a personas, obras, frutos, tierra, conciencia y acciones. Con 98 apariciones, esta acepción dominante recorre las parábolas y la enseñanza ética de los Evangelios: la «buena semilla» del Hijo del Hombre (Mt 13:24), las «buenas obras» que glorifican al Padre (Mt 5:16) y la «buena batalla» de la fe (1 Ti 6:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69994, 'spa', 'bello, hermoso', 'Estéticamente agradable, hermoso o atractivo en apariencia física: describe la belleza exterior de objetos o personas. Solo dos apariciones claras: Lc 21:5 describe el templo adornado con «piedras hermosas y ofrendas», y Mt 13:45 habla de «perlas hermosas». Esta acepción preserva el núcleo clásico de καλός como término estético, visible en el cognado κάλλος (belleza).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69998, 'spa', 'Buenos (topónimo)', 'Usado como componente de nombre propio en el topónimo Καλοὶ Λιμένες («Buenos Puertos»), el puerto en la costa sur de Creta donde ancló la nave de Pablo (Hch 27:8). Una sola aparición donde καλός funciona no como adjetivo vivo sino como elemento fosilizado de una designación geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70001, 'spa', 'Velo o cobertura', 'Velo o cobertura, usado tanto literal como figuradamente. En 2 Co 3:13 Pablo se refiere al velo que Moisés puso sobre su rostro; en 3:14-15 se transforma en metáfora de la cobertura espiritual que impide comprender el antiguo pacto; y en 3:16 el velo es quitado cuando uno se vuelve al Señor. Todo el uso se concentra en este único pasaje paulino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70002, 'spa', 'Cubrir, ocultar, velar', 'Colocar una cubierta sobre algo para esconderlo, ocultarlo o protegerlo de la vista. Se usa literalmente para las olas que engullen una barca (Mt 8:24) y figurativamente para el ocultamiento espiritual, como cuando Pablo dice que el evangelio está ''velado'' para los que se pierden (2 Co 4:3). Las traducciones multilingües — español ''cubrir'', francés ''couvrir'' — confirman un núcleo semántico único de ocultamiento físico o metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70008, 'spa', 'Bien, correctamente', 'Adverbio que afirma que una accion se realiza correcta, apropiada o encomiablemente, derivado del adjetivo καλός (''hermoso, bueno''). Se usa tanto con sinceridad — ''haras bien'' (Hch 15:29; 3 Jn 6) — como con ironia mordaz: ''bien rechazais el mandamiento de Dios'' (Mc 7:9). En la formula καλῶς ποιέω (''hacer bien/correctamente''), aparece en exhortaciones eticas (1 Co 7:37-38; Stg 2:8, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70011, 'spa', 'Camello', 'El camello, gran animal de carga del antiguo Cercano Oriente. Sus seis apariciones neotestamentarias se agrupan en dos conjuntos: el proverbio hiperbólico del camello por el ojo de una aguja, ilustrando la dificultad de los ricos para entrar al reino de Dios (Mt 19:24; Mr 10:25; Lc 18:25; cf. Mt 23:24), y la vestimenta de Juan el Bautista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70014, 'spa', 'Horno o fragua', 'Horno o fragua de calor extremo, usado para fundir, quemar o refinar. En Mt 13:42, 50, Jesús lo emplea en parábolas de juicio: los impíos son arrojados al horno de fuego. En Ap 1:15 los pies del Hijo del Hombre resplandecen como bronce refinado en un horno, y en Ap 9:2 sube humo como de una gran fragua. La imagen evoca purificación y juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70017, 'spa', 'Doblar la rodilla', 'Doblar o inclinar la rodilla como acto de adoracion, reverencia o sumision ante Dios. En Rom 11:4, Dios preservo siete mil que no doblaron la rodilla ante Baal; en Rom 14:11 la cita isaiana declara que toda rodilla se doblara; Ef 3:14 muestra a Pablo arrodillado en oracion ante el Padre; y Fil 2:10 proclama que toda rodilla se doblara ante Jesus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70018, 'spa', 'Aunque, aun si (concesiva)', 'Aunque, aun si (concesiva): La conjunción concesiva que significa ''aunque, aun si, aun cuando'', formada por crasis de καὶ ἐάν. Introduce cláusulas condicionales que expresan escenarios extremos o improbables cuya veracidad no altera la afirmación principal. En Mt 26:35 Pedro jura ''aunque tenga que morir contigo'', y en Mc 16:18 la promesa se mantiene ''aunque beban veneno mortal''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70024, 'spa', 'Al menos (partícula escalar)', 'Al menos (partícula escalar): Una partícula escalar o minimizadora que significa ''al menos, por lo menos'', expresando el mínimo absoluto de una expectativa o deseo. Solo aparece un caso claro en el NT: Hch 5:15, donde la gente sacaba a los enfermos a las calles para que ''al menos'' (κἄν) la sombra de Pedro cayera sobre ellos. El cambio del sentido concesivo al escalar es sutil pero real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70025, 'spa', 'Cana de Galilea', 'Cana de Galilea, aldea de importancia significativa en el Cuarto Evangelio. En Jn 2:1, 11 es donde Jesus realiza su primera senal en una boda; en Jn 4:46 se menciona nuevamente cuando Jesus regresa y sana al hijo del funcionario real a distancia; y en Jn 21:2 se identifica como el pueblo natal de Natanael. Su repetida aparicion la establece como marcador geografico y teologico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70027, 'spa', 'Título real etíope', 'Lucas usa Κανδάκη como título y no como nombre propio, reflejando el sistema real meroítico. La conversión de este alto funcionario etíope representa el evangelio cruzando fronteras raciales y geográficas: de Jerusalén a Judea y Samaria, ahora alcanzando hasta los confines de la tierra. El encuentro de Felipe con el eunuco cumple la promesa profética de la expansión universal del mensaje de salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70028, 'spa', 'Regla o norma', 'Regla, norma o vara de medir, usada figuradamente para un principio de conducta o una esfera definida de actividad. Pablo la emplea para delimitar los confines de su territorio apostolico, la ''medida'' que Dios le asigno (2 Co 10:13, 15-16), y como principio rector para la vida cristiana (Ga 6:16; Fil 3:16). Su etimologia de la regla del carpintero subyace a su fuerza metaforica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70029, 'spa', 'Capernaúm (nombre propio que designa la ciudad ubicada en la ribera noroeste del', 'Capernaúm (nombre propio que designa la ciudad ubicada en la ribera noroeste del mar de Galilea, sede del ministerio de Jesús durante su período galileo. Aparece en los cuatro Evangelios como sitio de milagros clave (Mc 1:21-28, Jn 2:12), enseñanzas y llamamiento de discípulos. La etimología hebrea ''aldea de Nahum'' se conserva en todas las traducciones mediante transliteración fonética.)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70031, 'spa', 'Traficar con el evangelio', 'Pablo emplea καπηλεύω para denunciar a quienes comercializan el evangelio. El verbo originalmente significaba venta al menudeo, pero adquirió connotaciones de adulteración: diluir el vino, manipular productos para lucrar. Pablo acusa a muchos predicadores de corromper la palabra de Dios por ganancia personal, mientras afirma la pureza de sus propios motivos ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70032, 'spa', 'Humo', 'Humo: vapor visible que surge del fuego o de la combustión, usado en el NT predominantemente en la imaginería apocalíptica y teofánica. El humo del incienso ante el trono de Dios (Ap 8:4) transmite adoración y presencia divina, mientras que el humo del abismo (Ap 9:2), de la destrucción de Babilonia (Ap 18:9, 18) y del tormento eterno (Ap 14:11; 19:3) señalan juicio y destrucción. El sermón de Pedro en Pentecostés cita a Joel: «vapor de humo» (Hch 2:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70035, 'spa', 'corazón (ser interior)', 'El ser interior o núcleo de la persona que abarca pensamiento, emoción, voluntad y orientación moral-espiritual. A lo largo de 158 apariciones, καρδία es el lugar de la fe (Ro 10:9), el entendimiento (Mt 13:15), la dureza (Mr 3:5) y la pureza (Mt 5:8). La notable estabilidad interlingüística —español corazón, francés coeur, alemán Herz, árabe قلب, coreano 마음— refleja la universalidad casi absoluta de esta metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70041, 'spa', 'fruto, producto, cosecha', 'Fruto o producto en sus dimensiones tanto literal como figurada. Literalmente abarca el rendimiento de árboles, viñas y campos (Mt 21:19, 34; Mr 12:2; Stg 5:7). Figuradamente denota el resultado moral o espiritual de la vida y acciones de una persona, como el ''fruto digno de arrepentimiento'' del Bautista (Mt 3:8), el principio de Jesús de que el árbol se conoce por su fruto (Mt 7:16-20) y el célebre ''fruto del Espíritu'' de Pablo (Gá 5:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70045, 'spa', 'Cristiano de Troas', 'La breve mención de Carpo por parte de Pablo preserva el nombre de un cristiano por lo demás desconocido que sirvió al apóstol. Este detalle testifica de las redes de creyentes ordinarios que sostuvieron el ministerio de Pablo: personas como Carpo que ofrecieron hospitalidad, custodiaron pertenencias y facilitaron la labor apostólica mediante servicio práctico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70047, 'spa', 'Dar fruto', 'Producir fruto, usado tanto para la cosecha agrícola literal (como cuando la semilla cae en buena tierra, Mc 4:28) como para la productividad espiritual figurada y la fecundidad moral en la vida del creyente (Ro 7:4; Col 1:10). La estructura compuesta — karpos (''fruto'') más phoreo (''llevar, cargar'') — se refleja transparentemente en traducciones romances como el español ''dar fruto'' y el francés ''porter du fruit'', preservando la imagen viva de llevar o producir cosecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70053, 'spa', 'Fértil y productivo', 'Pablo usa καρποφόρος para describir el cuidado providencial de Dios manifestado en la bendición agrícola. Las estaciones fructíferas apuntan a temporadas productivas. El argumento de Pablo es que, aun sin las Escrituras, los gentiles han conocido a Dios a través de la abundancia de la naturaleza: la lluvia y la cosecha dan testimonio de un Proveedor bondadoso, dejando a la humanidad sin excusa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70054, 'spa', 'Perseverancia por fe', 'Hebreos emplea καρτερέω para elogiar la persistencia de Moisés impulsada por la fe. Moisés dejó Egipto sin temer la ira del faraón porque mantenía sus ojos en el Rey invisible. El verbo capta la paradoja de la fe: ver lo que no se ve sostiene la resistencia en las pruebas visibles. La perseverancia de Moisés se convierte en paradigma para los creyentes que resisten no por lo que ven, sino por lo que creen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70055, 'spa', 'Mota, brizna, paja', 'Un diminuto trozo de materia seca —mota, astilla o brizna de paja— lo bastante pequeño como para pasar inadvertido en el ojo. En el NT aparece únicamente en la parábola de «la paja y la viga» (Mt 7:3-5; Lc 6:41-42), donde Jesús emplea el contraste entre un microscópico karphos y un enorme dokos para denunciar la hipocresía al juzgar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70056, 'spa', 'según, conforme a', 'Acepción dominante con 332 apariciones: señala conformidad con una norma, criterio o fundamento de juicio. Este uso con acusativo expresa que acciones, juicios o estados se ajustan a una medida: κατὰ τὸν νόμον (según la ley), κατὰ σάρκα (según la carne). El español según y conforme a captan con precisión esta función normativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70058, 'spa', 'por, a lo largo de', 'Extensión espacial a través de una región —«por toda», «a lo largo de»— con 24 apariciones en acusativo. Describe movimiento o presencia distribuida por un territorio: κατὰ τὴν Ἰουδαίαν (por toda Judea), κατὰ τὴν χώραν (por la región). Lucas señala que la fama de Jesús se extendió «por toda la región circundante» (Lc 4:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70059, 'spa', 'cada (distributivo)', 'Uso distributivo que indica asignación individual o repetición —«cada», «todo»— con 42 apariciones en acusativo. Expresiones como καθ᾿ ἡμέραν (diariamente), καθ᾿ ἕνα (uno por uno) y κατ᾿ οἶκον (de casa en casa) distribuyen la acción entre múltiples instancias. El español cada y por captan bien este reparto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70063, 'spa', 'en, entre (locativo)', 'Ubicación estática en un lugar concreto —«en», «entre»— con 23 apariciones en acusativo, sin implicar movimiento. José es advertido «en sueños» (κατ᾿ ὄναρ, Mt 1:20), o los sucesos ocurren «en el lugar». Este sentido locativo responde a la pregunta «¿dónde?» más que a «¿por dónde?» o «¿cómo?».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70064, 'spa', 'por (medio o modo)', 'Uso instrumental o modal que expresa medio, modo o circunstancia —«por», «con», «mediante»— con 19 apariciones en acusativo. Marcos señala que la enseñanza nueva viene «con autoridad» (κατ᾿ ἐξουσίαν, Mr 1:27), y Jesús aparta a los discípulos «en privado» (κατ᾿ ἰδίαν). El matiz se desplaza de la norma al instrumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70066, 'spa', 'a solas, en privado', 'Expresiones de privacidad, soledad o separación —«a solas», «aparte», «en privado»— con 10 apariciones en la frase fija κατ᾿ ἰδίαν y variantes. Jesús se retira frecuentemente con los discípulos «en privado» (Mt 14:13, 23; 17:1, 19). La frase, literalmente «según lo propio», se ha convertido en una expresión semifija.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70075, 'spa', 'abajo, hacia abajo', 'El sentido espacial originario con genitivo: movimiento descendente de arriba hacia abajo —«abajo», «por el despeñadero»— con cuatro apariciones. Los cerdos se precipitan «por el despeñadero» (κατὰ τοῦ κρημνοῦ, Mt 8:32, Mr 5:13, Lc 8:33) y Pablo habla de cubrirse «la cabeza» (κατὰ κεφαλῆς, 1 Co 11:4). Este es el núcleo etimológico del que brotan todos los sentidos metafóricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70077, 'spa', 'acerca de, respecto a', 'Indica el tema o punto de referencia del discurso —«acerca de», «respecto a», «en cuanto a»— con seis apariciones en acusativo. Pablo escribe de Epafras informando «acerca de vuestro amor» (Ef 1:15) y τὰ κατ᾿ ἐμέ (lo que a mí respecta, Ef 6:21). Félix tenía conocimiento «acerca del Camino» (Hch 24:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70078, 'spa', 'hacia, ante', 'Sentido direccional que indica movimiento u orientación hacia algo —«hacia», «ante», «de frente a»— con 13 apariciones en acusativo. Incluye κατὰ πρόσωπον (de frente, en presencia de) y κατὰ Κυρήνην (hacia Cirene, Hch 8:26). Simeón profetiza que el niño está «preparado ante la faz de todos los pueblos» (Lc 2:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70083, 'spa', 'sobremanera, en extremo', 'Expresiones de medida excesiva o grado superlativo —«sobremanera», «en extremo», «más allá de toda comparación»— con cuatro apariciones en frases como καθ᾿ ὑπερβολήν (desmesuradamente). Pablo describe tribulación «sobremanera» (2 Co 1:8), gloria «que sobrepasa toda comparación» (2 Co 4:17) y persecución «en extremo» (Gá 1:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70088, 'spa', 'contra, en oposición', 'Con genitivo, expresa oposición hostil —«contra»— con tres apariciones. Un viento impetuoso sopla «contra» la nave (Hch 27:14), y Judas advierte sobre impíos que hablan «cosas duras contra» el Señor (Jud 15). Este sentido adversativo se desarrolla naturalmente desde el movimiento descendente (presionar hacia abajo) hasta la hostilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (70128, 'spa', 'bajar, descender físicamente', 'Sentido central y dominante (79 ocurrencias): movimiento físico descendente de un lugar más alto a uno más bajo. Cubre personas que bajan de montes, viajan desde ciudades elevadas, descienden al agua, y figuras divinas o celestiales que descienden. Pasajes clave: el Espíritu descendiendo en el bautismo de Jesús (Mt 3:16), la lluvia cayendo sobre una casa (Mt 7:25) y el pan de vida que desciende del cielo (Jn 6:33).');